// Generated by tooling/unicode-cases/locale-case.ts; expected values are from Node.
// Oracle: Node 24.20.0; Unicode 17.0; ICU 78.3.
// docs/foundations/unicode.md: locale-sensitive casing and Staying identical to node.
const input = "\u0049\u0323\u0301";
const lower = input.toLocaleLowerCase("\u006c\u0074");
const upper = input.toLocaleUpperCase("\u006c\u0074");
assert.sameValue(lower, "\u0069\u0307\u0323\u0301");
assert.sameValue(lower.length, 4);
assert.sameValue(upper, "\u0049\u0323\u0301");
assert.sameValue(upper.length, 3);
